CREATE TABLE "app_settings" ("setting_key" TEXT NOT NULL, "setting_value" TEXT NOT NULL, PRIMARY KEY ("setting_key"));
CREATE TABLE "categories" ("owner_id" TEXT NULL, "household_id" TEXT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "sync_state" TEXT NOT NULL DEFAULT 'pending', "id" TEXT NOT NULL, "name" TEXT NOT NULL, "icon" TEXT NOT NULL, "kind" TEXT NOT NULL, "group_name" TEXT NOT NULL DEFAULT 'other', "sort_order" INTEGER NOT NULL DEFAULT 0, "is_default" INTEGER NOT NULL DEFAULT 0 CHECK ("is_default" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE "goal_contributions" ("owner_id" TEXT NULL, "household_id" TEXT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "sync_state" TEXT NOT NULL DEFAULT 'pending', "id" TEXT NOT NULL, "goal_id" TEXT NOT NULL REFERENCES goals (id), "amount_minor" INTEGER NOT NULL, "occurred_on" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "goals" ("owner_id" TEXT NULL, "household_id" TEXT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "sync_state" TEXT NOT NULL DEFAULT 'pending', "id" TEXT NOT NULL, "name" TEXT NOT NULL, "target_minor" INTEGER NOT NULL, "currency" TEXT NOT NULL, "target_date" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "outbox" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "target_table" TEXT NOT NULL, "row_id" TEXT NOT NULL, "op" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "attempts" INTEGER NOT NULL DEFAULT 0, "last_error" TEXT NULL);
CREATE TABLE "plan_items" ("owner_id" TEXT NULL, "household_id" TEXT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "sync_state" TEXT NOT NULL DEFAULT 'pending', "id" TEXT NOT NULL, "plan_id" TEXT NOT NULL REFERENCES plans (id), "group_name" TEXT NOT NULL, "name" TEXT NOT NULL, "category_id" TEXT NULL, "amount_minor" INTEGER NOT NULL, "is_fixed" INTEGER NOT NULL DEFAULT 0 CHECK ("is_fixed" IN (0, 1)), "sort_order" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
CREATE TABLE "plans" ("owner_id" TEXT NULL, "household_id" TEXT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "sync_state" TEXT NOT NULL DEFAULT 'pending', "id" TEXT NOT NULL, "template" TEXT NOT NULL, "income_minor" INTEGER NOT NULL, "currency" TEXT NOT NULL, "is_active" INTEGER NOT NULL DEFAULT 1 CHECK ("is_active" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE "recurring_rules" ("owner_id" TEXT NULL, "household_id" TEXT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "sync_state" TEXT NOT NULL DEFAULT 'pending', "id" TEXT NOT NULL, "type" TEXT NOT NULL, "amount_minor" INTEGER NOT NULL, "currency" TEXT NOT NULL, "category_id" TEXT NOT NULL REFERENCES categories (id), "note" TEXT NOT NULL DEFAULT '', "frequency" TEXT NOT NULL, "start_on" INTEGER NOT NULL, "next_run_on" INTEGER NOT NULL, "is_active" INTEGER NOT NULL DEFAULT 1 CHECK ("is_active" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE "transactions" ("owner_id" TEXT NULL, "household_id" TEXT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "sync_state" TEXT NOT NULL DEFAULT 'pending', "id" TEXT NOT NULL, "type" TEXT NOT NULL, "amount_minor" INTEGER NOT NULL, "currency" TEXT NOT NULL, "category_id" TEXT NOT NULL REFERENCES categories (id), "note" TEXT NOT NULL DEFAULT '', "occurred_on" INTEGER NOT NULL, "created_by" TEXT NULL, PRIMARY KEY ("id"));
